// Extract photo from Telegram update
const body = $input.first().json;
const message = body?.message;
const photo = message?.photo;

if (!photo || photo.length === 0) {
  // Send error message for non-photo content
  return [{
    json: {
      error: 'No photo detected',
      chatId: message?.chat?.id,
      username: message?.from?.username || 'Unknown'
    }
  }];
}

// Get the largest photo
const fileId = photo[photo.length - 1].file_id;
const chatId = message?.chat?.id;

return [{
  json: {
    fileId,
    chatId,
    username: message?.from?.username || 'Unknown',
    firstName: message?.from?.first_name || 'User'
  }
}];

// Construct full image URL
const filePath = $input.first().json.result.file_path;
const imageUrl = `https://api.telegram.org/file/bot${$credentials.telegramBotToken}/${filePath}`;

return [{
  json: {
    imageUrl,
    chatId: $('Extract Photo').first().json.chatId,
    username: $('Extract Photo').first().json.username,
    firstName: $('Extract Photo').first().json.firstName
  }
}];

// Check confidence threshold
const result = $input.first().json.data;
const confidence = result?.confidence || 0;
const chatId = $('Format Image URL').first().json.chatId;

if (confidence >= 0.8) {
  return [{
    json: {
      ...result,
      chatId,
      createIncident: true,
      severity: 'CRITICAL'
    }
  }];
} else if (confidence >= 0.5) {
  return [{
    json: {
      ...result,
      chatId,
      createIncident: false,
      severity: 'WARNING'
    }
  }];
}

return [{
  json: {
    ...result,
    chatId,
    createIncident: false,
    severity: 'NORMAL'
  }
}];

// Format improved notification for user
const result = $input.first().json;
const timestamp = new Date().toLocaleString('en-US', { 
  timeZone: 'Africa/Addis_Ababa',
  dateStyle: 'medium',
  timeStyle: 'short'
});

let message = '';

if (result.createIncident) {
  message = `🦠 <b>Disease Detected!</b>\n`;
  message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `<b>Disease:</b> ${result.disease}\n`;
  message += `<b>Confidence:</b> ${(result.confidence * 100).toFixed(0)}%\n`;
  message += `<b>Severity:</b> 🔴 CRITICAL\n\n`;
  message += `<b>Recommendation:</b>\n${result.recommendation}\n\n`;
  message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `✅ <b>An incident has been created.</b>\n`;
  message += `Our agronomist will contact you within 2 hours.\n\n`;
  message += `<b>Immediate Actions:</b>\n`;
  message += `• Isolate affected plants\n`;
  message += `• Avoid spreading to healthy crops\n`;
  message += `• Prepare for treatment application\n\n`;
  message += `<i>Analysis completed: ${timestamp}</i>`;
} else if (result.severity === 'WARNING') {
  message = `⚠️ <b>Possible Disease Detected</b>\n`;
  message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `<b>Disease:</b> ${result.disease}\n`;
  message += `<b>Confidence:</b> ${(result.confidence * 100).toFixed(0)}%\n`;
  message += `<b>Severity:</b> 🟡 WARNING\n\n`;
  message += `<b>Recommendation:</b>\n${result.recommendation}\n\n`;
  message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `<b>Suggested Actions:</b>\n`;
  message += `• Monitor the affected area closely\n`;
  message += `• Take another photo in 2-3 days\n`;
  message += `• Contact agronomist if condition worsens\n\n`;
  message += `<i>Analysis completed: ${timestamp}</i>`;
} else {
  message = `✅ <b>No Significant Disease Found</b>\n`;
  message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `The image analysis did not detect any major disease issues.\n\n`;
  if (result.recommendation) {
    message += `<b>General Advice:</b>\n${result.recommendation}\n\n`;
  }
  message += `<b>Continue with:</b>\n`;
  message += `• Regular monitoring\n`;
  message += `• Standard maintenance\n`;
  message += `• Scheduled inspections\n\n`;
  message += `<i>Analysis completed: ${timestamp}</i>`;
}

return [{
  json: {
    chatId: result.chatId,
    message,
    severity: result.severity,
    createIncident: result.createIncident
  }
}];

// Format admin alert if disease detected
const result = $input.first().json;
const timestamp = new Date().toLocaleString('en-US', { 
  timeZone: 'Africa/Addis_Ababa',
  dateStyle: 'medium',
  timeStyle: 'short'
});

if (!result.createIncident && result.severity !== 'WARNING') {
  return [];
}

const severityEmoji = result.severity === 'CRITICAL' ? '🔴' : '🟡';

return [{
  json: {
    message: `${severityEmoji} <b>New Disease Alert</b>\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n\n` +
      `<b>Disease:</b> ${result.disease}\n` +
      `<b>Confidence:</b> ${(result.confidence * 100).toFixed(0)}%\n` +
      `<b>Severity:</b> ${result.severity}\n\n` +
      `<b>Action:</b> ${result.recommendation}\n\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n\n` +
      `<b>Next Steps:</b>\n` +
      `• Create incident in EFMS\n` +
      `• Assign agronomist to field\n` +
      `• Schedule treatment\n\n` +
      `<i>Alert generated: ${timestamp}</i>`,
    severity: result.severity
  }
}];

// Error handler with detailed context
const error = $input.first().json.error || {};
const timestamp = new Date().toLocaleString('en-US', { 
  timeZone: 'Africa/Addis_Ababa',
  dateStyle: 'medium',
  timeStyle: 'short'
});

return {
  json: {
    errorMessage: error.message || error.code || 'Analysis failed',
    errorDetails: JSON.stringify(error, null, 2),
    workflow: 'Image Disease Detection',
    timestamp: timestamp,
    severity: 'CRITICAL'
  }
};

// Handle non-photo messages gracefully
const item = $input.first().json;

if (item.error === 'No photo detected') {
  return [{
    json: {
      chatId: item.chatId,
      message: `❌ <b>No Photo Detected</b>\n\n━━━━━━━━━━━━━━━━━━━━━━\n\nPlease send a clear photo of the affected plant.\n\n<b>Tips for best results:</b>\n• Focus on the affected area\n• Ensure good lighting\n• Capture the whole leaf if possible\n\n<i>Need help? Contact support.</i>`,
      parseMode: 'HTML'
    }
  }];
}

return [];
